// sounds.js is embedded in template.html along with the other client files
// it is the asset data for the ui sound effects: 14 short ogg clips as data urls, filled into
// g_sound_effects at load; the play() calls live in main.js, ui.js and dispatch.js

if (typeof window != 'undefined')
{
    g_sound_effects = {
        connected: new Audio("data:audio/ogg;base64,"),
        user_entered_your_channel: new Audio("data:audio/mp3;base64,"),
        user_joined_your_channel: new Audio("data:audio/mp3;base64,"),
        channel_created: new Audio("data:audio/mp3;base64,"),
        channel_switched: new Audio("data:audio/mp3;base64,"),
        channel_edited: new Audio("data:audio/mp3;base64,"),
        channel_deleted: new Audio("data:audio/mp3;base64,"),
        user_left_your_channel: new Audio("data:audio/mp3;base64,"),
        user_disconnected_from_your_channel: new Audio("data:audio/mp3;base64,"),
        poke: new Audio("data:audio/mp3;base64,"),
        message_sent: new Audio("data:audio/mp3;base64,"),
        message_received: new Audio("data:audio/mp3;base64,"),
        call: new Audio("data:audio/mpeg;base64,"),
        insufficient_permissions: new Audio("data:audio/mpeg;base64,")
    };
}

/**
 * @brief applies the sound-effects toggle to every clip's muted flag
 *        authoritative: even a play() that skipped the g_are_sound_effects_enabled check stays silent
 *
 * @return void
 */
function sounds__apply_sound_effects_muted()
{
    if (g_sound_effects == null) { return; }
    let muted = (g_are_sound_effects_enabled == false);
    for (let key in g_sound_effects)
    {
        if (g_sound_effects[key] && typeof g_sound_effects[key].muted !== "undefined")
        {
            g_sound_effects[key].muted = muted;
        }
    }
}
